{
  "title": "A Surprising Cusco Day",
  "summary": "A gentle day around the old centre with a twist: after the must-see Qorikancha, we wander the artisan lanes of San Blas and end with a quiet meal, skipping the usual big sights.",
  "stops": [
    {
      "poi_id": "p2",
      "kind": "activity",
      "must_do_id": "m2",
      "note": "We keep the golden temple, because some stories must be told twice.",
      "must_do_id": "m2"
    },
    {
      "poi_id": "p6",
      "kind": "activity",
      "must_do_id": null,
      "note": "A surprise for the photo and market lovers: tiny workshops, blue doors, and no crowds.",
      "must_do_id": null
    },
    {
      "poi_id": "p18",
      "kind": "meal",
      "must_do_id": null,
      "note": "A low-key lunch with proper vegetarian plates, the kind locals keep for themselves.",
      "must_do_id": null
    },
    {
      "poi_id": "p5",
      "kind": "activity",
      "must_do_id": null,
      "note": "We close the afternoon with the Cathedral, a heavy history lesson softened by the quiet hour.",
      "must_do_id": null
    },
    {
      "poi_id": "p19",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner at Morena, where the crew can rest their feet and share the day's unexpected finds.",
      "must_do_id": null
    }
  ]
}
